//go:build ignore

package main
import("encoding/json";"fmt";"os";"strings";"math/rand";"sort";"github.com/Tencent/WeKnora/internal/sourceloc";"github.com/Tencent/WeKnora/internal/types")
type B struct{Start int `json:"start"`;End int `json:"end"`;Locator types.SourceLocator `json:"locator"`}
type I struct{Name string `json:"name"`;Text string `json:"text"`;Blocks []B `json:"blocks"`;Start int `json:"start"`;End int `json:"end"`;Expected types.SourceLocators `json:"expected"`;At []A `json:"at"`}
type A struct{Position int `json:"position"`;Expected types.SourceLocators `json:"expected"`}
type T struct{Text string `json:"text"`;Expected []B `json:"expected"`;Pass []B `json:"pass"`}
type Q struct{Text string `json:"text"`;Expected string `json:"expected"`}
type R struct{Old string `json:"old"`;New string `json:"new"`;Blocks []B `json:"blocks"`;Expected []B `json:"expected"`}
type AL struct{Markdown string `json:"markdown"`;Units []sourceloc.Unit `json:"units"`;Expected []B `json:"expected"`}
type C struct{CSV string `json:"csv"`;Units []sourceloc.Unit `json:"units"`;Markdown string `json:"markdown"`;Expected []B `json:"expected"`}
type M struct{First,Second,Expected types.SourceLocators}
func blocks(in []types.SourceBlock)[]B{out:=make([]B,0,len(in));for _,b:=range in{out=append(out,B{b.Start,b.End,b.Locator})};return out}
func main(){entityPath:="/tmp/weknora-source-location/resources/go-html-entities.json";outPath:="/tmp/weknora-source-location/fixtures/source-location-golden.json";if len(os.Args)>1{entityPath=os.Args[1]};if len(os.Args)>2{outPath=os.Args[2]};var indexes []I;add:=func(name,text string,bs []types.SourceBlock,start,end int){idx:=sourceloc.NewIndex(text,bs);c:=I{Name:name,Text:text,Blocks:blocks(bs),Start:start,End:end,Expected:idx.Locators(start,end)};for _,p:=range []int{-1,0,1,2,len([]rune(text))/2,len([]rune(text))-1,len([]rune(text)),len([]rune(text))+4}{c.At=append(c.At,A{p,idx.LocatorsAt(p)})};indexes=append(indexes,c)}
 texts:=[]string{"","one","one\n","one\n\ntwo"," \t\r\n\n","\ufeffOne\n\n二🙂","\ufeff","a\r\n\r\n b\t\n","  first\n second\n\n\nthird  ","x\n\u00a0\n\ny","## 标题\n\n**正文** [链接](url) ![图](image)",strings.Repeat("😀",500)}
 var ts []T;for i,text:=range texts{bs:=sourceloc.TextBlocks(text);body:=strings.TrimPrefix(text,"\ufeff");pass:=sourceloc.TextBlocks(body);if body!=text{for i:=range pass{pass[i].Start++;pass[i].End++}};ts=append(ts,T{text,blocks(bs),blocks(pass)});for _,r:=range [][2]int{{0,len([]rune(text))},{-5,5000},{2,8},{5,2},{10000,11000}}{add(fmt.Sprintf("text%d-%v",i,r),text,bs,r[0],r[1])};add(fmt.Sprintf("pass%d",i),text,pass,0,len([]rune(text)))}
 gaps:=[]string{"", "\n\n", "---", "[ ](https://a)", "![visible](https://a)","<b></b>","<!--note-->","???", "🙂", "\u0301", "unmapped", "其他", "5%", "<", "=", "＆", "&nbsp;", "&amp;", "&lt;", "&NotEqual;", "&frac12;", "\U0001e4d0", "\U0001e4f0", "\u00b2", "＆amp;", "&#4294967361;", "&#x;"}
 for i,gap:=range gaps{text:="AA"+gap+"BB";n:=len([]rune(text));add(fmt.Sprintf("gap%d",i),text,[]types.SourceBlock{{Start:0,End:2,Locator:types.SourceLocator{Type:"pdf",Page:1}},{Start:n-2,End:n,Locator:types.SourceLocator{Type:"pdf",Page:2}}},0,n)}
 for _,typ:=range []string{"pdf","slide","section","sheet","text","time","word","other"}{for variant:=0;variant<7;variant++{loc:=types.SourceLocator{Type:typ,Page:1,Slide:1,Section:1,Sheet:"Sheet1",RowStart:1,RowEnd:1,Start:0,End:2,StartMs:10,EndMs:20,Title:"first"};second:=loc;second.RowStart=2;second.RowEnd=3;second.Start=4;second.End=6;second.Title="second";switch variant{case 1:second.Mapping="exact";case 2:second.Partial=true;case 3:second.SourceID="another";case 4:second.SourceHash="hash";case 5:second.Page=2;second.Slide=2;second.Section=2;second.Sheet="Another";second.Start=5;case 6:second.BBox=[]float64{0.1,0.2,0.3,0.4}}
 add(fmt.Sprintf("fold%s%d",typ,variant),"AA  BB",[]types.SourceBlock{{Start:0,End:2,Locator:loc},{Start:4,End:6,Locator:second}},0,6)}}
 rng:=rand.New(rand.NewSource(123));for i:=0;i<80;i++{text:="AA 一二🙂 BB\nCC *** DD\n\nEE";n:=len([]rune(text));var bs []types.SourceBlock;for j:=0;j<7;j++{start:=rng.Intn(n+4)-2;end:=start+rng.Intn(n+2);bs=append(bs,types.SourceBlock{Start:start,End:end,Locator:types.SourceLocator{Type:[]string{"pdf","text","word","time","section"}[rng.Intn(5)],Page:rng.Intn(3),Start:start,End:end,Section:rng.Intn(3)}})};add(fmt.Sprintf("overlap%d",i),text,bs,-2,n+2)}
 quotes:=[]string{"![x](abc) [link](url) <b>word</b>","&#x; &#; &#XG; &#0; &#13; &#4294967361; &#x100000041;",strings.Repeat("😀中",400),"a\u00a0b\u0085c\nd\te", "<!-- x\ny --> <tag\n x> hi", "[x](a(b)) ![i](a(b))"};entityBytes,_:=os.ReadFile(entityPath);var entities map[string]string;json.Unmarshal(entityBytes,&entities);names:=make([]string,0,len(entities));for k:=range entities{names=append(names,k)};sort.Strings(names);for _,k:=range names{quotes=append(quotes,"&"+k,"&"+strings.TrimSuffix(k,";")+"suffix")};var qs []Q;for _,q:=range quotes{qs=append(qs,Q{q,sourceloc.CleanQuote(q)})}
 var merges []M;for _,loc:=range []types.SourceLocator{{Type:"pdf",Page:1,Quote:"one"},{Type:"text",Start:3,End:6},{Type:"pdf",Page:1,BBox:[]float64{0,1},Title:"title"}}{first:=types.SourceLocators{loc};for i:=0;i<4;i++{other:=loc;switch i{case 1:other.Title="changed";case 2:other.Quote="changed";case 3:other.SourceHash="changed"};second:=types.SourceLocators{other};merges=append(merges,M{first,second,sourceloc.MergeLocators(first,second)})}}
 var remaps []R;var aligns []AL;for i,pair:=range [][2]string{{"First\r\n\r\nSecond","First\n\nSecond"},{"AA\n\nBB","AA\n\nNEW\n\nBB"},{"AA\n\nBB","AA\n\nchanged"},{"AA\n\nAA","AA\n\nAA"},{"AA\n\nAA","AA"},{"![x](old) Intro\n\n2.5% < 7","![x](new-long-url) Intro\n\n2.5% < 7"},{"| A | B |\n| --- | --- |\n| C | D |","<table><tr><td>A</td><td>B</td></tr><tr><td>C</td><td>D</td></tr></table>"},{"A &amp; B","A & B"},{"-- １２.５％ --","12.5%"},{"[Link](old)","[Link](new)"},{"\U0001e4d0\U0001e4f0","\U0001e4d0\U0001e4f0!"},{"only one",""},{"","new"}}{for variant:=0;variant<3;variant++{bs:=sourceloc.TextBlocks(pair[0]);if variant==1{bs=[]types.SourceBlock{{Start:0,End:len([]rune(pair[0])),Locator:types.SourceLocator{Type:"text",End:len([]rune(pair[0]))}}}};if variant==2{bs=append(bs,types.SourceBlock{Start:-1,End:10000,Locator:types.SourceLocator{Type:"pdf",Page:1}})};remaps=append(remaps,R{pair[0],pair[1],blocks(bs),blocks(sourceloc.RemapBlocks(bs,pair[0],pair[1]))})};_ = i}
for _,markdown:=range []string{"# Alpha\n\n1. Beta", "Alpha\nAlpha\nBeta", "125 12 1.2 １２", "<b>Alpha</b> ![Beta](url)", "A &amp; B\n\nC &NotEqual; D", "garay \U0001e4d0\U0001e4f0", "First\r\n\r\nSecond", "(12345678901234567) Alpha\nBeta", "<5 >5 ≥5 5% -5 1.5 1,5 1/5 1:5", "x😀y😀z", ""}{for _,keys:=range [][]string{{"Alpha","Beta"},{"Alpha","Alpha","Beta"},{"12","125","1.2"},{"A & B","C ≠ D"},{"First","Second"},{"<5","5%","-5","1.5"},{"x😀y","z"},{"garay \U0001e4d0\U0001e4f0"}}{var units []sourceloc.Unit;for i,key:=range keys{units=append(units,sourceloc.Unit{Text:key,Locator:types.SourceLocator{Type:"pdf",Page:i+1}})};aligns=append(aligns,AL{markdown,units,blocks(sourceloc.Align(markdown,units))})}}
var csvs []C;for _,csv:=range []string{"", "a,b\nc,d", "a,b\r\nc,d\r\n", "a\n\n b", "a,b\nc", " , \nword,value", "\"quoted\nline\",v\nword,value", "a,\"lazy\"text\nword,value", "\ufeffa,b\nx,y", "中国,😀\n3%,4.5"}{units,e:=sourceloc.StructureUnits("csv",[]byte(csv));if e!=nil{panic(e)};for _,markdown:=range []string{"| a | b |\n| --- | --- |\n| c | d |\n", "word value\n中国 😀\n3% 4.5", csv}{csvs=append(csvs,C{csv,units,markdown,blocks(sourceloc.Align(markdown,units))})}}
result:=map[string]interface{}{"remaps":remaps,"alignments":aligns,"csv":csvs,"indexes":indexes,"texts":ts,"quotes":qs,"merges":merges};b,e:=json.Marshal(result);if e!=nil{panic(e)};os.WriteFile(outPath,b,0600);fmt.Println("index",len(indexes),"text",len(ts),"quote",len(qs),"merge",len(merges),"remap",len(remaps),"align",len(aligns),"csv",len(csvs))}
